if(['127.0.0.1','localhost'].includes(location.hostname))document.querySelector('.local-auth-note').hidden=false;
const form=document.querySelector('#admin-code-form');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('button'),error=document.querySelector('#login-error');button.disabled=true;error.textContent='';try{const response=await fetch('/api/admin/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:form.elements.code.value})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Tidak dapat masuk.');location.href='/admin';}catch(e){error.textContent=e.message;button.disabled=false;}});
